import { defaultTransformer, ynodeToPmnode } from "@y/prosemirror";
import * as d from "lib0/delta";
import { Node } from "prosemirror-model";
import type { Transaction } from "prosemirror-state";
import { type Block, type BlockNoteEditor, type BlockSchema, type InlineContentSchema, type PartialBlock, type StyleSchema } from "../index.js";
import * as Y from "@y/y";
/**
 * The Y ⇄ ProseMirror pipeline of the collaboration binding (see
 * `YSyncExtension`): attributions become `y-attributed-*` marks and nested
 * `blockGroup`s are persistent (kept in Y, hidden while empty, merged in the
 * view). Every conversion outside a bound editor goes through the same
 * pipeline, so a document imported with `blocksToYDoc` gets its groups and one
 * read with `yDocToBlocks` hides the empty ones.
 */
export declare const blockNoteTransformer: ReturnType<typeof defaultTransformer>;
/**
 * Find the equivalent of a Y.Node in another Y.Doc.
 *
 * For root types this looks up the matching shared key; for sub-types it
 * locates the item by its client/clock ID in the target doc's store.
 */
export declare function findTypeInOtherYdoc<T extends Y.Node<any>>(ytype: T, otherYdoc: Y.Doc): T;
/**
 * Collect all stored Yjs ID ranges belonging to a fragment, including deleted
 * descendants. Items belonging to other shared types are excluded.
 *
 * Resolves the fragment in the supplied document and scans its stored items:
 * walking visible content would miss deleted subtrees. To include all deleted
 * descendants, the document or update must retain them; content already
 * garbage-collected cannot be recovered here.
 *
 * Updates are loaded into a temporary document with `gc: false`, which is
 * destroyed after collection. Caller-provided documents are never destroyed.
 */
export declare function collectFragmentIds(fragment: Y.Node, docOrUpdate: Uint8Array | Y.Doc): Y.IdSet;
/**
 * Turn Prosemirror JSON to BlockNote style JSON
 * @param editor BlockNote editor
 * @param json Prosemirror JSON
 * @returns BlockNote style JSON
 */
export declare function _prosemirrorJSONToBlocks<BSchema extends BlockSchema, ISchema extends InlineContentSchema, SSchema extends StyleSchema>(editor: BlockNoteEditor<BSchema, ISchema, SSchema>, json: any): Block<BSchema, ISchema, SSchema>[];
/**
 * Turn BlockNote JSON to Prosemirror node / state
 * @param editor BlockNote editor
 * @param blocks BlockNote blocks
 * @returns Prosemirror root node
 */
export declare function _blocksToProsemirrorNode<BSchema extends BlockSchema, ISchema extends InlineContentSchema, SSchema extends StyleSchema>(editor: BlockNoteEditor<BSchema, ISchema, SSchema>, blocks: PartialBlock<BSchema, ISchema, SSchema>[]): Node;
/**
 * Turn a Y.Node collaborative doc into a BlockNote document (BlockNote style JSON of all blocks)
 * @param editor BlockNote editor
 * @param fragment Y.Node
 * @returns BlockNote document (BlockNote style JSON of all blocks)
 */
export declare function yfragmentToBlocks<BSchema extends BlockSchema, ISchema extends InlineContentSchema, SSchema extends StyleSchema>(editor: BlockNoteEditor<BSchema, ISchema, SSchema>, fragment: Y.Node): Block<BSchema, ISchema, SSchema>[];
/**
 * Convert blocks to a Y.Node
 *
 * This can be used when importing existing content to Y.Doc for the first time,
 * note that this should not be used to rehydrate a Y.Doc from a database once
 * collaboration has begun as all history will be lost
 *
 * @param editor BlockNote editor
 * @param blocks the blocks to convert
 * @param fragment XML fragment name
 * @returns Y.Node
 */
export declare function blocksToYType<BSchema extends BlockSchema, ISchema extends InlineContentSchema, SSchema extends StyleSchema>(editor: BlockNoteEditor<BSchema, ISchema, SSchema>, blocks: Block<BSchema, ISchema, SSchema>[], fragment?: Y.Node): Y.Node<any>;
/**
 * Turn a Y.Doc collaborative doc into a BlockNote document (BlockNote style JSON of all blocks)
 * @param editor BlockNote editor
 * @param ydoc Y.Doc
 * @param fragment XML fragment name
 * @returns BlockNote document (BlockNote style JSON of all blocks)
 */
export declare function yDocToBlocks<BSchema extends BlockSchema, ISchema extends InlineContentSchema, SSchema extends StyleSchema>(editor: BlockNoteEditor<BSchema, ISchema, SSchema>, ydoc: Y.Doc, fragment?: string): Block<BSchema, ISchema, SSchema>[];
/**
 * This can be used when importing existing content to Y.Doc for the first time,
 * note that this should not be used to rehydrate a Y.Doc from a database once
 * collaboration has begun as all history will be lost
 *
 * @param editor BlockNote editor
 * @param blocks the blocks to convert
 * @param fragment XML fragment name
 */
export declare function blocksToYDoc<BSchema extends BlockSchema, ISchema extends InlineContentSchema, SSchema extends StyleSchema>(editor: BlockNoteEditor<BSchema, ISchema, SSchema>, blocks: PartialBlock<BSchema, ISchema, SSchema>[], fragment?: string): Y.Doc;
/**
 * Diff two ProseMirror documents into a delta, using BlockNote's node-pairing
 * policy ({@link blockMatchNodes}) so a block's content-type change is reported
 * as a replace rather than a schema-invalid in-place edit.
 */
export declare function docDiffToDelta(previousDoc: Node, newDoc: Node): d.Delta<d.DeltaConf>;
/**
 * Append steps that render a Y node into the transaction's current document.
 * Supports both plain and already-attributed documents, replacing old preview
 * marks with the renderer's attributions using BlockNote's node-pairing policy.
 * Defaults to the binding's pipeline ({@link blockNoteTransformer}). Does not
 * dispatch or write to the Y node; the caller controls sync configuration and
 * dispatch.
 */
export declare function yNodeToTransaction(tr: Transaction, node: Y.Node, options?: NonNullable<Parameters<typeof ynodeToPmnode>[2]>): Transaction;
